use split_decls_genesis :: ourprelude :: * ; use std :: { cmp , ops } ; use rustc_span :: { DUMMY_SP , Span } ; #[doc = " Tracks whether executing a node may exit normally (versus"] #[doc = " return/break/panic, which \"diverge\", leaving dead code in their"] #[doc = " wake). Tracked semi-automatically (through type variables marked"] #[doc = " as diverging), with some manual adjustments for control-flow"] #[doc = " primitives (approximating a CFG)."] #[derive (Copy , Clone , Debug , PartialEq , Eq , PartialOrd , Ord)] pub (crate) enum Diverges { #[doc = " Potentially unknown, some cases converge,"] #[doc = " others require a CFG to determine them."] Maybe , #[doc = " Definitely known to diverge and therefore"] #[doc = " not reach the next sibling or its parent."] Always { #[doc = " The `Span` points to the expression"] #[doc = " that caused us to diverge"] #[doc = " (e.g. `return`, `break`, etc)."] span : Span , #[doc = " In some cases (e.g. a `match` expression"] #[doc = " where all arms diverge), we may be"] #[doc = " able to provide a more informative"] #[doc = " message to the user."] #[doc = " If this is `None`, a default message"] #[doc = " will be generated, which is suitable"] #[doc = " for most cases."] custom_note : Option < & 'static str > , } , #[doc = " Same as `Always` but with a reachability"] #[doc = " warning already emitted."] WarnedAlways , } impl ops :: BitAnd for Diverges { type Output = Self ; fn bitand (self , other : Self) -> Self { cmp :: min (self , other) } } impl ops :: BitOr for Diverges { type Output = Self ; fn bitor (self , other : Self) -> Self { cmp :: max (self , other) } } impl ops :: BitAndAssign for Diverges { fn bitand_assign (& mut self , other : Self) { * self = * self & other ; } } impl ops :: BitOrAssign for Diverges { fn bitor_assign (& mut self , other : Self) { * self = * self | other ; } } impl Diverges { #[doc = " Creates a `Diverges::Always` with the provided `span` and the default note message."] pub (super) fn always (span : Span) -> Diverges { Diverges :: Always { span , custom_note : None } } pub (super) fn is_always (self) -> bool { self >= Diverges :: Always { span : DUMMY_SP , custom_note : None } } }